// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 waitSeconds, address actor, address ref) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(ref != address(0));
        c.seedMarket(1000);
        vm.prank(actor);
        c.getFreeKilo();
        uint256 before = c.Kilos(actor);
        // ensure at least one full production period has elapsed so newKilo >= 1
        uint256 elapsed = bound(waitSeconds, c.DRUGS_TO_PRODUCE_1KILO(), type(uint48).max);
        vm.warp(block.timestamp + elapsed);
        vm.prank(actor);
        c.collectDrugs(ref);
        uint256 afterKilos = c.Kilos(actor);
        // General rule: collecting drugs only accumulates kilos; the balance never falls below what the user held.
        assertTrue(afterKilos >= before, "collectDrugs decreased kilos");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.seedMarket(1000);
    }

    function testFuzz_property(address actor, uint256 elapsed) public {
        vm.assume(actor != address(0));
        elapsed = bound(elapsed, 1, 30 days);

        vm.prank(actor);
        c.getFreeKilo();
        uint256 kilosBefore = c.Kilos(actor);
        vm.assume(kilosBefore > 0);

        vm.warp(block.timestamp + elapsed);
        vm.prank(actor);
        c.collectDrugs(address(0));

        uint256 kilosAfter = c.Kilos(actor);
        // General rule: one collect may at most double the caller's kilos.
        assertTrue(kilosAfter <= 2 * kilosBefore);
    }
}

